SELECT ticker, MAX(fiscal_year) AS fiscal_year, MAX(value) AS total_assets 
FROM v_total_assets 
WHERE ticker = 'NVDA';

SELECT (v_revenue.value - v_revenue_wal.value) AS revenue_difference
FROM (
    SELECT MAX(value) as value FROM v_revenue WHERE ticker = 'AMZN'
) v_revenue
JOIN (
    SELECT MAX(value) as value FROM v_revenue WHERE ticker = 'WMT'
) v_revenue_wal;
